$(document).ready(function(){$("#license_form").on("submit",function(e){e.preventDefault();var n=$("#license_input_text").val();$.post(OC.generateUrl("/license/license"),{licenseString:n}).done(function(){location.reload()}).fail(function(){OC.Notification.showTemporary(t("core","Error")),$("#license_input_text").focus()})}),$("#license_remove_button").click(function(){OC.dialogs.confirm(t("settings","Remove current support key"),t("settings","Enterprise Support Key"),function(e){e&&$.ajax({url:OC.generateUrl("/license/license"),type:"DELETE"}).done(function(){location.reload()}).fail(function(){OC.Notification.showTemporary(t("core","Error"))})},!0)})});